def restore_barcodes(apps, schema_editor):
    Product = apps.get_model("store", "Product")
    ProductEAN = apps.get_model("store", "ProductEAN")

    seen_products = set()
    for ean in ProductEAN.objects.order_by("id"):
        if ean.product_id in seen_products:
            continue
        seen_products.add(ean.product_id)
        Product.objects.filter(id=ean.product_id).update(barcode=ean.code)


